describe('Dialog in JSDOM', () => {
    it('uses an accessible fallback and forwards attributes and the host ref', () => {
        const ref = createRef<HTMLDialogElement>();
        const { getByRole } = render(
            <Dialog ref={ref} open aria-label="Example" data-testid="dialog-host" className="example">
